        required: false,
        autocomplete: "tel",
        helperText: "Optional. Use digits, spaces, dashes, parentheses, or a leading +, such as +1 555 123 4567."
      }
    ];

    function escapeHtml(value) {
      return String(value)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#039;");
    }

    function validateForm(values) {
      const nextErrors = {};
      const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      const phonePattern = /^\+?[0-9\s().-]{7,20}$/;

      if (!values.fullName.trim()) {
        nextErrors.fullName = "Full name is required.";
      }

      if (!values.email.trim()) {
        nextErrors.email = "Email address is required.";
      } else if (!emailPattern.test(values.email.trim())) {
        nextErrors.email = "Enter a valid email address.";
      }

      if (values.phone.trim() && !phonePattern.test(values.phone.trim())) {
        nextErrors.phone = "Enter a valid phone number using digits, spaces, dashes, parentheses, or +.";
      }

      return nextErrors;
    }

    function FormField(field) {
      const error = state.errors[field.id];
      const describedBy = [
        field.helperText ? `${field.id}-helper` : "",
        error ? `${field.id}-error` : ""
      ].filter(Boolean).join(" ");

      return `
        <div class="form-field">
          <label for="${field.id}">${field.label}${field.required ? " *" : ""}</label>
          <input
            id="${field.id}"
            name="${field.id}"
            type="${field.type}"
            value="${escapeHtml(state[field.id])}"
            placeholder="${field.placeholder}"
            autocomplete="${field.autocomplete}"
            ${field.required ? "required" : ""}
            aria-invalid="${error ? "true" : "false"}"
            ${describedBy ? `aria-describedby="${describedBy}"` : ""}
          >
          ${field.helperText ? `<p class="helper-text" id="${field.id}-helper">${field.helperText}</p>` : ""}
          <p class="error-message" id="${field.id}-error" aria-live="polite">${error || ""}</p>
        </div>
      `;
    }

    function ContactForm() {
      return `
        <section class="support-page" aria-labelledby="support-title">
          <div class="contact-card">
            <div class="contact-content">
              <p class="eyebrow">Support request</p>
              <h1 id="support-title">How can we help?</h1>
              <p class="intro">Send our support team your contact details and we will get back to you as soon as possible.</p>
              <form id="support-form" novalidate>
                ${fields.map(FormField).join("")}
                <button type="submit">Submit support request</button>
                <p class="success-message ${state.submitted ? "is-visible" : ""}" aria-live="polite">
                  Thanks! Your support request is ready to send.
                </p>
              </form>
            </div>
          </div>
        </section>
      `;
    }

    function render() {
      document.getElementById("app").innerHTML = ContactForm();
      document.getElementById("support-form").addEventListener("input", handleInput);
      document.getElementById("support-form").addEventListener("submit", handleSubmit);
    }

    function handleInput(event) {
      const { name, value } = event.target;

      if (!Object.prototype.hasOwnProperty.call(state, name)) {
        return;
